def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    S = data[0]
    Q = int(data[1])

    queries = []
    for i in range(Q):
        L1 = int(data[2 + 4 * i]) - 1
        R1 = int(data[3 + 4 * i]) - 1
        L2 = int(data[4 + 4 * i]) - 1
        R2 = int(data[5 + 4 * i]) - 1
        queries.append((L1, R1, L2, R2))

    results = []
    for L1, R1, L2, R2 in queries:
        if S[L1:R1+1] == S[L2:R2+1]:
            results.append("Yes")
        else:
            results.append("No")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
